SELECT 
FROM CAM_RU_ELEMENT_INSTANCE
WHERE partition_id = #{partitionId} AND element_instance_key = #{key}

SELECT element_instance_key
FROM CAM_RU_ELEMENT_INSTANCE
WHERE partition_id = #{partitionId} AND tenant_id = #{tenantId}
  AND bpmn_process_id = #{bpmnProcessId} AND business_id = #{businessId}
ORDER BY element_instance_key

SELECT 
FROM CAM_RU_TAKEN_SEQUENCE_FLOW
WHERE partition_id = #{partitionId} AND flow_scope_key = #{key.flowScopeKey}
  AND gateway_element_id = #{key.gatewayElementId}
  AND sequence_flow_element_id = #{key.sequenceFlowElementId}

SELECT 
FROM CAM_RU_TAKEN_SEQUENCE_FLOW
WHERE partition_id = #{partitionId} AND flow_scope_key = #{flowScopeKey}

  AND gateway_element_id = #{gatewayElementId}

ORDER BY gateway_element_id, sequence_flow_element_id

mapper.update:
UPDATE CAM_RU_TAKEN_SEQUENCE_FLOW
SET times_taken = #{row.timesTaken}
WHERE partition_id = #{partitionId} AND flow_scope_key = #{row.flowScopeKey}
  AND gateway_element_id = #{row.gatewayElementId}
  AND sequence_flow_element_id = #{row.sequenceFlowElementId}

